/* =========================================================
   CAMPUS AUTOPILOT — VALIDATE FORM FIELDS
   Version: 2026-11-04-v4
   Mode: Run Once for Each Item
========================================================= */

"use strict";

// ---------------------------------------------------------
// 1. READ WEBHOOK INPUT
// ---------------------------------------------------------

const input = $json;

let body = input;
let bodyParseError = "";

if (typeof input.body === "string") {
  try {
    body = JSON.parse(input.body);
  } catch (error) {
    body = {};
    bodyParseError = "Invalid JSON received from webhook.";
  }
} else if (
  input.body &&
  typeof input.body === "object" &&
  !Array.isArray(input.body)
) {
  body = input.body;
}

if (!body || typeof body !== "object" || Array.isArray(body)) {
  body = {};
}

// Read fields from parsed body or original input.
function getField(...keys) {
  for (const source of [body, input]) {
    if (!source || typeof source !== "object") continue;

    for (const key of keys) {
      const value = source[key];

      if (
        value !== undefined &&
        value !== null &&
        String(value).trim() !== ""
      ) {
        return value;
      }
    }
  }

  return "";
}

// ---------------------------------------------------------
// 2. YEAR MAPPING
// ---------------------------------------------------------

const yearMap = {
  "FY": 1,
  "SY": 2,
  "TY": 3,
  "Final Year": 4
};

// ---------------------------------------------------------
// 3. BRANCH AND DIVISION MAPPING
// ---------------------------------------------------------

const allowedDivisions = {
  1: {
    CSE: ["A", "B", "C"],
    "CSE-DS": ["D"],
    "CSE-AIML": ["E", "F"],
    ENTC: ["G"],
    Chemical: ["H"],
    Civil: ["I"],
    Mechanical: ["J"]
  },
  2: {
    CSE: ["A", "B", "C"],
    "CSE-DS": ["A", "B"],
    "CSE-AIML": ["A", "B"],
    ENTC: ["A", "B"],
    Chemical: ["A", "B"],
    Civil: ["A", "B"],
    Mechanical: ["A", "B"]
  },
  3: {
    CSE: ["A", "B", "C"],
    "CSE-DS": ["A", "B"],
    "CSE-AIML": ["A", "B"],
    ENTC: ["A", "B"],
    Chemical: ["A", "B"],
    Civil: ["A", "B"],
    Mechanical: ["A", "B"]
  },
  4: {
    CSE: ["A", "B", "C"],
    "CSE-DS": ["A", "B"],
    "CSE-AIML": ["A", "B"],
    ENTC: ["A", "B"],
    Chemical: ["A", "B"],
    Civil: ["A", "B"],
    Mechanical: ["A", "B"]
  }
};

// ---------------------------------------------------------
// 4. EXTRACT FORM DATA
// ---------------------------------------------------------

const title = String(
  getField("Title", "title")
).trim();

const message = String(
  getField("Message", "message")
).trim();

const year = String(
  getField("Year", "academicYear", "year")
).trim();

const mappedYear = yearMap[year] || 0;

const suppliedYearNumber = getField(
  "Year Number",
  "year_num",
  "year_number"
);

const yearNum =
  suppliedYearNumber === ""
    ? mappedYear
    : Number(suppliedYearNumber);

const branch = String(
  getField("Branch", "branch")
).trim();

const division = String(
  getField("Division", "division")
).trim().toUpperCase();

const recipientType = String(
  getField("Recipient Type", "recipient_type")
).trim().toLowerCase();

const sendMode = String(
  getField("Send Mode", "send_mode")
).trim().toLowerCase();

const publishMode = String(
  getField("Publish Mode", "publish_mode")
).trim().toLowerCase();

const scheduledDate = String(
  getField(
    "Scheduled Date",
    "Schedule Date",
    "scheduled_date"
  )
).trim();

const scheduledTime = String(
  getField(
    "Scheduled Time",
    "Schedule Time",
    "scheduled_time"
  )
).trim();

const timezone = String(
  getField("Timezone", "timezone") || "Asia/Kolkata"
).trim();

// ---------------------------------------------------------
// 5. PRODUCTION CONFIRMATION
// ---------------------------------------------------------

const confirmationKeys = [
  "production_confirmed",
  "productionConfirmed",
  "Production Confirmed",
  "production-confirmed"
];

const confirmationValues = [];

for (const source of [body, input]) {
  if (!source || typeof source !== "object") continue;

  for (const key of confirmationKeys) {
    if (
      Object.prototype.hasOwnProperty.call(source, key)
    ) {
      confirmationValues.push({
        key,
        value: source[key]
      });
    }
  }
}

function isExplicitTrue(value) {
  if (value === true || value === 1) {
    return true;
  }

  if (typeof value === "string") {
    return ["true", "1", "yes", "on"].includes(
      value.trim().toLowerCase()
    );
  }

  return false;
}

const productionConfirmed = confirmationValues.some(
  item => isExplicitTrue(item.value)
);

const productionRequested = sendMode === "production";

// This node records confirmation only.
// It does not grant live-send authorization.

const liveSendAuthorized = false;
const liveBroadcastAuthorized = false;

// ---------------------------------------------------------
// 6. VALIDATION
// ---------------------------------------------------------

const errors = [];

if (bodyParseError) {
  errors.push(bodyParseError);
}

if (!title) {
  errors.push("Title is required.");
}

if (title.length > 120) {
  errors.push("Title exceeds 120 characters.");
}

if (!message) {
  errors.push("Message is required.");
}

if (message.length > 5000) {
  errors.push("Message exceeds 5000 characters.");
}

if (recipientType !== "classroom") {
  errors.push(
    "Only specific classroom announcements are supported."
  );
}

if (!mappedYear) {
  errors.push("Invalid academic year.");
}

if (mappedYear && yearNum !== mappedYear) {
  errors.push(
    "Academic year and year number do not match."
  );
}

const allowedBranches = [
  "CSE",
  "CSE-DS",
  "CSE-AIML",
  "ENTC",
  "Chemical",
  "Civil",
  "Mechanical"
];

if (!allowedBranches.includes(branch)) {
  errors.push("Invalid branch.");
}

const validDivisions =
  allowedDivisions[mappedYear]?.[branch] || [];

if (!division) {
  errors.push("Division is required.");
} else if (!validDivisions.includes(division)) {
  errors.push(
    "Invalid division for selected year and branch."
  );
}

if (!["production", "test"].includes(sendMode)) {
  errors.push("Invalid send mode.");
}

if (!["immediate", "scheduled"].includes(publishMode)) {
  errors.push("Invalid publishing mode.");
}

if (productionRequested && !productionConfirmed) {
  errors.push("Production confirmation is required.");
}

// ---------------------------------------------------------
// 7. SCHEDULE VALIDATION
// ---------------------------------------------------------

if (publishMode === "scheduled") {
  if (!scheduledDate || !scheduledTime) {
    errors.push(
      "Schedule date and time are required."
    );
  }

  if (
    scheduledDate &&
    !/^\d{4}-\d{2}-\d{2}$/.test(scheduledDate)
  ) {
    errors.push("Invalid schedule date format.");
  }

  if (
    scheduledTime &&
    !/^([01]\d|2[0-3]):[0-5]\d$/.test(scheduledTime)
  ) {
    errors.push("Invalid schedule time format.");
  }

  if (
    /^\d{4}-\d{2}-\d{2}$/.test(scheduledDate) &&
    /^([01]\d|2[0-3]):[0-5]\d$/.test(scheduledTime)
  ) {
    const parsedDate = new Date(
      `${scheduledDate}T${scheduledTime}:00+05:30`
    );

    const datePart = new Date(
      `${scheduledDate}T00:00:00Z`
    );

    if (
      Number.isNaN(datePart.getTime()) ||
      datePart.toISOString().slice(0, 10) !== scheduledDate
    ) {
      errors.push("Invalid calendar date.");
    } else if (Number.isNaN(parsedDate.getTime())) {
      errors.push("Invalid schedule date or time.");
    } else if (parsedDate.getTime() <= Date.now()) {
      errors.push(
        "Scheduled time must be in the future."
      );
    }
  }
}

if (
  publishMode === "immediate" &&
  ((scheduledDate && !scheduledTime) ||
   (!scheduledDate && scheduledTime))
) {
  errors.push("Incomplete schedule information.");
}

// ---------------------------------------------------------
// 8. FINAL VALIDATION
// ---------------------------------------------------------

const valid = errors.length === 0;

// ---------------------------------------------------------
// 9. BUILD NOTICE TEXT
// ---------------------------------------------------------

let noticeText = String(
  getField("Notice Text", "notice_text") ||
  `Title: ${title}\n\n${message}`
);

if (publishMode === "scheduled") {
  noticeText +=
    `\n\nScheduled Date: ${scheduledDate}` +
    `\nScheduled Time: ${scheduledTime}` +
    `\nTimezone: ${timezone}`;
}

// ---------------------------------------------------------
// 10. RETURN OUTPUT
// ---------------------------------------------------------

return {
  json: {
    valid,
    errors,

    title,
    message,
    notice_text: noticeText,

    year,
    year_label: year,
    year_num: mappedYear,

    branch,
    division,

    recipient_type: recipientType,
    audience:
      getField("Audience", "audience") ||
      "Specific Classroom",

    publish_mode: publishMode,

    scheduled_date: scheduledDate || null,
    scheduled_time: scheduledTime || null,

    timezone,

    send_mode: sendMode,
    test_mode: sendMode === "test",

    production_requested: productionRequested,
    production_confirmed: productionConfirmed,

    live_send_authorized: liveSendAuthorized,
    live_broadcast_authorized: liveBroadcastAuthorized,

    source:
      getField("Source", "source") ||
      "Campus Autopilot Website",

    submitted_at:
      getField("Submitted At", "submitted_at") ||
      new Date().toISOString(),

    original_payload: body,

    debug: {
      validation_code_version: "2026-11-04-v4",

      received_year: year,
      mapped_year_number: mappedYear,
      received_year_number: suppliedYearNumber,

      received_branch: branch,
      received_division: division,
      received_send_mode: sendMode,

      received_production_confirmation:
        confirmationValues,

      parsed_production_confirmation:
        productionConfirmed,

      confirmation_source_count:
        confirmationValues.length,

      validation_error_count: errors.length,

      body_was_parsed:
        typeof input.body === "string",

      body_parse_error: bodyParseError,
      received_body_type: typeof input.body,

      extracted_title: title,
      extracted_message_length: message.length,
      extracted_recipient_type: recipientType,
      extracted_publish_mode: publishMode
    }
  }
};

"use strict";

// =====================================================
// 1. GET ORIGINAL FORM DATA
// =====================================================

const form = $("Validate Form Fields").item.json;
const j = $json;

// =====================================================
// 2. REQUIRED EXTRACTION FIELDS
// =====================================================

const keys = [
  "event_type",
  "title",
  "description",
  "venue",
  "branch",
  "year",
  "division",
  "start_date",
  "start_time",
  "end_date",
  "end_time",
  "deadline",
  "links",
  "summary"
];

const clean = {};

keys.forEach(key => {
  clean[key] = null;
});

clean.links = [];

// =====================================================
// 3. READ AI RESPONSE
// =====================================================

let raw = "";

if (j.error) {
  raw = "";
} else if (Array.isArray(j.content)) {
  const textBlock = j.content.find(
    block => block.type === "text"
  );

  raw = textBlock?.text || "";
} else {
  raw = j.text || j.output || "";
}

// =====================================================
// 4. PARSE AI JSON
// =====================================================

let ai = null;
let aiOk = false;
let aiError = null;

if (j.error) {
  aiError =
    "AI service error: " +
    (j.error.message || JSON.stringify(j.error)).slice(0, 200);

} else if (!raw.trim()) {
  aiError = "AI response was empty";

} else {
  try {
    const cleaned = String(raw)
      .replace(/^\uFEFF/, "")
      .replace(/^\s*```(?:json)?\s*/i, "")
      .replace(/\s*```\s*$/, "")
      .trim();

    const parsed = JSON.parse(cleaned);

    if (
      parsed &&
      typeof parsed === "object" &&
      !Array.isArray(parsed)
    ) {
      ai = parsed;
      aiOk = true;
    } else {
      aiError = "AI response was not a JSON object";
    }

  } catch (error) {
    aiError =
      "AI response was incomplete or invalid JSON: " +
      error.message;
  }
}

// =====================================================
// 5. COPY EXTRACTED FIELDS
// =====================================================

if (aiOk) {
  keys.forEach(key => {
    if (ai[key] !== undefined) {
      clean[key] = ai[key];
    }
  });
}

// =====================================================
// 6. VALIDATE DATE AND TIME FORMATS
// =====================================================

const dateOk = value => {
  if (
    typeof value !== "string" ||
    !/^\d{4}-\d{2}-\d{2}$/.test(value)
  ) {
    return false;
  }

  const date = new Date(value + "T00:00:00Z");

  return !Number.isNaN(date.getTime()) &&
    date.toISOString().slice(0, 10) === value;
};

const timeOk = value => {
  if (
    typeof value !== "string" ||
    !/^\d{2}:\d{2}$/.test(value)
  ) {
    return false;
  }

  const [hours, minutes] = value.split(":").map(Number);

  return hours >= 0 &&
    hours <= 23 &&
    minutes >= 0 &&
    minutes <= 59;
};

// Validate dates
if (!dateOk(clean.start_date)) {
  clean.start_date = null;
}

if (!dateOk(clean.end_date)) {
  clean.end_date = null;
}

if (!dateOk(clean.deadline)) {
  clean.deadline = null;
}

// Validate times
if (!timeOk(clean.start_time)) {
  clean.start_time = null;
}

if (!timeOk(clean.end_time)) {
  clean.end_time = null;
}

// Validate links
if (!Array.isArray(clean.links)) {
  clean.links = [];
}

// =====================================================
// 7. FORM DATE AND TIME TAKE PRIORITY
// =====================================================

if (dateOk(form.scheduled_date)) {
  clean.start_date = form.scheduled_date;
}

if (timeOk(form.scheduled_time)) {
  clean.start_time = form.scheduled_time;
}

// =====================================================
// 8. VALIDATE REQUIRED EVENT INFORMATION
// =====================================================

const nonEmptyString = value =>
  typeof value === "string" &&
  value.trim().length > 0;

const requiredFieldsPresent =
  aiOk &&
  nonEmptyString(clean.title) &&
  nonEmptyString(clean.description) &&
  nonEmptyString(clean.venue) &&
  dateOk(clean.start_date) &&
  timeOk(clean.start_time) &&
  dateOk(clean.end_date) &&
  timeOk(clean.end_time);

// =====================================================
// 9. CHECK EVENT TIME RANGE
// =====================================================

let validTimeRange = false;

if (
  dateOk(clean.start_date) &&
  timeOk(clean.start_time) &&
  dateOk(clean.end_date) &&
  timeOk(clean.end_time)
) {
  const start = new Date(
    `${clean.start_date}T${clean.start_time}:00+05:30`
  );

  const end = new Date(
    `${clean.end_date}T${clean.end_time}:00+05:30`
  );

  validTimeRange =
    !Number.isNaN(start.getTime()) &&
    !Number.isNaN(end.getTime()) &&
    end > start;
}

// =====================================================
// 10. FINAL AI VALIDATION STATUS
// =====================================================

const finalAiOk =
  requiredFieldsPresent &&
  validTimeRange;

if (aiOk && !requiredFieldsPresent) {
  aiError =
    "AI extraction incomplete: title, description, venue, or event date/time is missing or invalid.";

} else if (requiredFieldsPresent && !validTimeRange) {
  aiError =
    "Invalid event time range: end must be after start.";
}

// =====================================================
// 11. RETURN RESULT
// =====================================================

return {
  json: Object.assign({}, form, {
    ai_ok: finalAiOk,
    ai_error: aiError,
    extracted: clean,
    debug: Object.assign({}, form.debug || {}, {
      parser_version: "2026-11-04-v5",
      ai_response_received: Boolean(raw),
      ai_response_length: raw.length,
      ai_json_valid: aiOk,
      required_event_fields_present: requiredFieldsPresent,
      valid_event_time_range: validTimeRange
    })
  })
};

/* =========================================================
   CAMPUS AUTOPILOT
   Filter Classroom Students
   Mode: Run Once for All Items
   ========================================================= */

// 1. Get all student records from Google Sheets
const rows = $input.all().map(item => item.json);

// 2. Get classroom criteria from Validate Form Fields
let criteria;

try {
    criteria = $("Validate Form Fields").first().json;
} catch (error) {
    return [{
        json: {
            success: false,
            error: "Unable to read Validate Form Fields node",
            details: error.message,
            received_rows: rows.length
        }
    }];
}

// 3. Read and normalize criteria
const targetYear = Number(criteria.year_num);

const targetBranch = String(criteria.branch || "")
    .trim()
    .toUpperCase();

const targetDivision = String(criteria.division || "")
    .trim()
    .toUpperCase();

// 4. Validate criteria
if (
    !Number.isFinite(targetYear) ||
    !targetBranch ||
    !targetDivision
) {
    return [{
        json: {
            success: false,
            error: "Invalid classroom selection",
            criteria: {
                year_num: criteria.year_num,
                branch: criteria.branch,
                division: criteria.division
            },
            received_rows: rows.length
        }
    }];
}

// 5. Filter matching students
const matchedStudents = rows.filter(student => {

    const studentYear = Number(student.Year);

    const studentBranch = String(student.Branch || "")
        .trim()
        .toUpperCase();

    const studentDivision = String(student.Division || "")
        .trim()
        .toUpperCase();

    const email = String(student.Email || "").trim();

    return (
        studentYear === targetYear &&
        studentBranch === targetBranch &&
        studentDivision === targetDivision &&
        email !== ""
    );
});

// 6. Return a diagnostic item if no students match
if (matchedStudents.length === 0) {
    return [{
        json: {
            success: false,
            message: "No students found for the selected classroom",
            criteria: {
                year_num: targetYear,
                branch: targetBranch,
                division: targetDivision
            },
            available_rows: rows.length,
            matched_students: 0
        }
    }];
}

// 7. Return one output item per matching student
return matchedStudents.map(student => ({
    json: {
        success: true,
        roll_no: student.Roll_No,
        name: student.Name,
        email: String(student.Email).trim(),
        year: Number(student.Year),
        branch: student.Branch,
        division: student.Division
    }
}));

/* =========================================================
   CAMPUS AUTOPILOT
   VALIDATE AND DEDUPLICATE RECIPIENTS
   Version: Production-safe recipient validation

   INPUT:
   Filter Classroom Students

   CONTEXT:
   Parse AI Response

   TEST MODE:
   Sends only to project owner's Gmail.

   PRODUCTION MODE:
   Sends only to matching students.
   Excludes owner's Gmail.
   Requires explicit production confirmation.
   ========================================================= */

"use strict";

// =========================================================
// 1. CONFIGURATION
// =========================================================

const OWNER_EMAIL = "ghorpadeatharva87@gmail.com";
const MAX_RECIPIENTS = 300;

const normalize = value =>
  String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");

const normalizeDivision = value =>
  normalize(value)
    .replace(/^division\s*/, "")
    .replace(/^div\s*/, "")
    .replace(/[^a-z0-9]/g, "");

const normalizeYear = value => {
  const v = normalize(value).replace(/[^a-z0-9]/g, "");

  const map = {
    sy: "2",
    secondyear: "2",
    second: "2",
    ndyear: "2",
    ty: "3",
    thirdyear: "3",
    third: "3",
    finalyear: "4",
    fourthyear: "4",
    fourth: "4",
    fy: "1",
    firstyear: "1",
    first: "1",
    "2": "2",
    "3": "3",
    "4": "4",
    "1": "1"
  };

  return map[v] || v;
};

const normalizeBranch = value => {
  const v = normalize(value)
    .replace(/[^a-z0-9]/g, "");

  const aliases = {
    cse: "cse",
    computerscience: "cse",
    computerscienceandengineering: "cse",
    cs: "cse",

    cseds: "cse-ds",
    csdatascience: "cse-ds",
    computersciencedatascience: "cse-ds",
    cseai: "cse-aiml",
    cseaiml: "cse-aiml",
    computerscienceandengineeringaiml: "cse-aiml",

    entc: "entc",
    electronicsandtelecommunication: "entc",
    electronicsandtelecommunicationengineering: "entc",

    mechanical: "mechanical",
    mechanicalengineering: "mechanical",

    civil: "civil",
    civilengineering: "civil"
  };

  return aliases[v] || v;
};

const validEmail = email =>
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);


// =========================================================
// 2. READ ORIGINAL NOTICE CONTEXT
// =========================================================

let ctx;

try {
  ctx = $("Parse AI Response").first().json;
} catch (error) {
  throw new Error(
    "Cannot read Parse AI Response node. Check its node name."
  );
}

const extracted = ctx.extracted || {};


// =========================================================
// 3. READ STUDENT DATA
// =========================================================

const inputItems = $input.all();

const rawRows = inputItems.map(item => item.json);

// Support records containing nested student objects.

const students = [];

for (const row of rawRows) {
  if (!row || typeof row !== "object") continue;
  if (row.error || row.success === false) continue;

  const nested =
    row.student ||
    row.data ||
    row.record ||
    row;

  if (Array.isArray(nested)) {
    students.push(...nested);
  } else if (nested && typeof nested === "object") {
    students.push(nested);
  }
}


// =========================================================
// 4. FLEXIBLE FIELD EXTRACTION
// =========================================================

function getField(obj, aliases) {
  if (!obj || typeof obj !== "object") return "";

  const keys = Object.keys(obj);

  for (const alias of aliases) {
    const key = keys.find(
      k => normalize(k).replace(/[^a-z0-9]/g, "") ===
           normalize(alias).replace(/[^a-z0-9]/g, "")
    );

    if (key !== undefined && obj[key] !== null) {
      return obj[key];
    }
  }

  return "";
}

function getStudentBranch(student) {
  return getField(student, [
    "branch",
    "Branch",
    "department",
    "Department",
    "course",
    "Course"
  ]);
}

function getStudentYear(student) {
  return getField(student, [
    "year",
    "Year",
    "year_label",
    "year_num",
    "year_number",
    "academic_year",
    "Academic Year",
    "class"
  ]);
}

function getStudentDivision(student) {
  return getField(student, [
    "division",
    "Division",
    "div",
    "Div",
    "section",
    "Section"
  ]);
}

function getStudentEmail(student) {
  return getField(student, [
    "email",
    "Email",
    "student_email",
    "Student Email",
    "email_address",
    "Email Address",
    "email_id",
    "E-mail"
  ]);
}

function getStudentName(student) {
  return getField(student, [
    "name",
    "Name",
    "student_name",
    "Student Name",
    "full_name"
  ]);
}


// =========================================================
// 5. SELECTED CLASS INFORMATION
// =========================================================

const selectedBranch = normalizeBranch(
  ctx.branch || ctx.extracted?.branch
);

const selectedYear = normalizeYear(
  ctx.year_num ??
  ctx.year_label ??
  ctx.year ??
  ctx.extracted?.year
);

const selectedDivision = normalizeDivision(
  ctx.division || ctx.extracted?.division
);


// =========================================================
// 6. MATCH STUDENTS
// =========================================================

const matchedStudents = students.filter(student => {

  const branch = normalizeBranch(
    getStudentBranch(student)
  );

  const year = normalizeYear(
    getStudentYear(student)
  );

  const division = normalizeDivision(
    getStudentDivision(student)
  );

  return (
    branch === selectedBranch &&
    year === selectedYear &&
    division === selectedDivision
  );
});


// =========================================================
// 7. VALIDATE AND DEDUPLICATE EMAILS
// =========================================================

const emailMap = new Map();

