const endDate = e.end_date || e.start_date;
let endISO = null;
if (scheduled) {
  if (endKnown) endISO = endDate + 'T' + e.end_time + ':00+05:30';
  else { const d = new Date(startISO); d.setHours(d.getHours() + 1); endISO = d.toISOString(); }
}
const startMs = scheduled ? new Date(startISO).getTime() : NaN;
const endMs = scheduled ? new Date(endISO).getTime() : NaN;
const invalidRange = scheduled && (isNaN(startMs) || isNaN(endMs) || endMs <= startMs);

let events = []; let checkFailed = false;
if (scheduled) {
  try {
    const all = $('Check Calendar Conflicts').all().map(i => i.json);
    if (all.some(x => x && x.error)) checkFailed = true;
    events = all.filter(x => x && x.id && x.status !== 'cancelled');
  } catch (err) { checkFailed = true; }
}
const toMs = v => { if (!v) return NaN; return String(v).length === 10 ? new Date(v + 'T00:00:00+05:30').getTime() : new Date(v).getTime(); };
const norm = s => String(s || '').trim().toLowerCase();
let conflicts = []; let existing = null;
if (scheduled && !invalidRange) {
  for (const x of events) {
    const s = toMs(x.start && (x.start.dateTime || x.start.date));
    const en = toMs(x.end && (x.end.dateTime || x.end.date));
    if (isNaN(s) || isNaN(en)) continue;
    // Genuine overlap only: the existing event must start before our end AND end after our start
    if (s < endMs && en > startMs) {
      const c = { id: x.id, summary: x.summary || '(no title)', start: x.start && (x.start.dateTime || x.start.date), end: x.end && (x.end.dateTime || x.end.date), link: x.htmlLink || null };
      conflicts.push(c);
      if (!existing && norm(x.summary) === norm(e.title) && Math.abs(s - startMs) < 60000) existing = c;
    }
  }
}
const can_create_event = sufficient && !invalidRange && !checkFailed && conflicts.length === 0 && ctx.calendar_allowed === true && ctx.preflight_ok === true;
return [{ json: Object.assign({}, ctx, { scheduled, calendar_conflicts: conflicts, has_conflict: conflicts.length > 0, duplicate_event: !!existing, existing_event: existing, calendar_check_failed: checkFailed, event_time_sufficient: sufficient, end_time_assumed: scheduled && !endKnown, invalid_time_range: invalidRange, can_create_event, event_start: startISO, event_end: endISO, timezone: 'Asia/Kolkata' }) }];

