  overall = 'TEST_' + overall;
}

// ---------------------------------------------------------
// 5. BUILD ERROR DETAILS
// ---------------------------------------------------------

const errs = [];

errs.push('MODE=' + mode);

if (!m.test_mode) {
  errs.push(
    'Approval: ' + (m.approval_status || 'UNKNOWN')
  );
}

if (!m.ai_ok && m.ai_error) {
  errs.push('AI: ' + m.ai_error);
}

if (
  m.calendar_status === 'FAILED' ||
  m.calendar_status === 'SKIPPED'
) {
  errs.push(
    'Calendar ' +
    m.calendar_status +
    ': ' +
    (m.calendar_reason || '')
  );
}

const blockReasons = Array.isArray(m.block_reasons)
  ? m.block_reasons
  : [];

if (!m.send_allowed && blockReasons.length) {
  errs.push(
    'Send blocked: ' + blockReasons.join(', ')
  );
}

if (m.test_mode && m.send_allowed) {
  errs.push(
    'Test mode: only the test address received the email. ' +
    classCount +
    ' class recipients were NOT emailed.'
  );
}

if (
  Array.isArray(m.invalid_emails) &&
  m.invalid_emails.length
) {
  errs.push(
    m.invalid_emails.length +
    ' invalid email(s) skipped'
  );
}

failures.forEach(f => {
  errs.push('Email ' + f);
});

// ---------------------------------------------------------
// 6. SAVE WORKFLOW LOG
// ---------------------------------------------------------

const sd = $getWorkflowStaticData('global');

sd.sent = sd.sent || {};
sd.log = sd.log || [];

// IMPORTANT:
// This key must match the duplicate-check key used
// in Validate and Deduplicate Recipients.

sd.campusAutopilotNotices =
  sd.campusAutopilotNotices || {};

const entry = {
  at: new Date().toISOString(),
  mode,
  hash: m.notice_hash || '',
  status,
  class_recipients: classCount,
  sent: sentCount,
  failed: failedCount,
  overall_status: overall
};

// Record a production notice after at least one
// email is accepted by Gmail.

if (
  m.send_allowed === true &&
  !m.test_mode &&
  sentCount > 0 &&
  m.notice_hash
) {
  sd.campusAutopilotNotices[m.notice_hash] = entry.at;
  sd.sent[m.notice_hash] = entry.at;
}

sd.log.push(entry);

if (sd.log.length > 50) {
  sd.log.shift();
}

// ---------------------------------------------------------
// 7. BUILD FINAL EXECUTION REPORT
// ---------------------------------------------------------

const preview = m.preview || {};

const finalRecipients =
  Array.isArray(preview.recipients)
    ? preview.recipients
    : recipientEmails;

return [
  {
    json: {
      status,
      overall_status: overall,
      mode,
      test_mode: m.test_mode === true,

      redirected_to_test: !!m.redirected_to_test,

      approval_status: m.approval_status,

      send_blocked_because: blockReasons,

      class_recipient_count: classCount,
      recipient_count: recipientCount,

      recipients_preview: finalRecipients,

      owner_email_excluded_from_production:
        m.test_mode === true ||
        !finalRecipients.some(
          email =>
            String(email).trim().toLowerCase() ===
            OWNER_EMAIL
        ),

      invalid_emails: m.invalid_emails || [],
      duplicate_emails_removed:
        m.duplicate_emails_removed || 0,

      sent_count: sentCount,
      failed_count: failedCount,

      failures,
      per_recipient: perRecipient,

      delivery_note:
        'Sent count means accepted by the Gmail API, not confirmed delivered to the inbox.',

      calendar_status: m.calendar_status,
      calendar_reason: m.calendar_reason,
      calendar_event_id: m.calendar_event_id,
      calendar_event_link: m.calendar_event_link,
      calendar_conflicts: m.calendar_conflicts || [],

      ai_ok: m.ai_ok,
      ai_error: m.ai_error,

      subject: m.subject,
      message_preview: m.message_text || '',

      log_row: {
        Execution_ID: String($execution.id),
        Submitted_At: m.submitted_at,
        Branch: m.branch,
        Year: m.year_label,
        Division: m.division,

        Notice_Summary: (
          (m.extracted && m.extracted.summary) ||
          m.notice_text ||
          ''
        ).slice(0, 300),

        Recipients_Count: classCount,
        Emails_Sent: sentCount,
        Emails_Failed: failedCount,

        Calendar_Status: m.calendar_status,
        Calendar_Event_ID: m.calendar_event_id || '',
        Calendar_Event_Link: m.calendar_event_link || '',

        Overall_Status: overall,

        Error_Details: errs.join(' | ').slice(0, 900)
      }
    }
  }
];
